			function doCalDayCnt(oNewDatCnt1,oNewDatCnt2){
			    
			    console.log("등록일수 계산 :::::" + oNewDatCnt1);
			    
			    var sAtendDayCnt = ""; // 출석일수
			    var dsPrdList = app.lookup("dsPrdList");    
			    for(var i=0; i<dsPrdList.getRowCount(); i++) {
			//        sAtendDayCnt =  getSum(dsPrdList.getValue(i,"ATEND_DAYCNT"));                
			//        sAtendDayCnt =  "getSum(/"ATEND_DAYCNT/")";
			    }    
			    console.log("출석일수 계산 :::::" + sAtendDayCnt);
			//    returnValue.copyToDataSet(dsPrdList, "CBX2=='1'"); // 선택한 것들만 가져옴
			    
			    // TODO 등록일수에 출석일수도 sum해야함
			    var a = app.lookup("ipb1");       // 출석일수
			    var b = app.lookup("ipbAbsncDayCntDiss");   // 결석일수_질병
			    var c = app.lookup("ipb7");                 // 결석일수_미인정
			    var d = app.lookup("ipb12");                // 결석일수_기타
			    var e = app.lookup("ipbRegDayCnt");         // 등록일수
			    
			    var sum = 
			              cpr.utils.Util.toNumber(a.value) + 
			              cpr.utils.Util.toNumber(b.value) +
			              cpr.utils.Util.toNumber(c.value) +
			              cpr.utils.Util.toNumber(d.value);
			     
			    e.value = sum;
			}

